const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const racers=[['Jordan','JOR','🇯🇴'],['Palestine','PLE','🇵🇸'],['Israel','ISR','🇮🇱'],['Russia','RUS','🇷🇺'],['Iran','IRN','🇮🇷'],['Pakistan','PAK','🇵🇰'],['China','CHN','🇨🇳'],['North Korea','PRK','🇰🇵']];
let selected=0,W=innerWidth,H=innerHeight,DPR=1,mode='menu',last=0,player={distance:0,lateral:0,speed:0,item:false,boost:0,drift:0,lap:1,elapsed:0},ais=[],keys={},touch={},toastTimer=0,beepCtx=null;
const TRACK=4800,LAPS=3,VIEW=1500,MAXSPEED=306,boxLocations=Array.from({length:10},(_,i)=>260+i*455);
const $=id=>document.getElementById(id);
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
function drawBall(c,x,y,r,index){c.save();c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.clip();const top=y-r;let colors=[['#111','#fff','#168c49'],['#111','#fff','#168c49'],['#fff','#fff','#fff'],['#fff','#2455a5','#e33b44'],['#169447','#fff','#e63d43'],['#138746','#138746','#138746'],['#e33336','#e33336','#e33336'],['#1664a2','#df2635','#1664a2']][index];
if(index===2){c.fillStyle='#fff';c.fillRect(x-r,top,2*r,2*r);c.fillStyle='#2d58a8';c.fillRect(x-r,top+r*.28,2*r,r*.12);c.fillRect(x-r,top+r*1.04,2*r,r*.12);c.strokeStyle='#2d58a8';c.lineWidth=Math.max(1,r*.07);for(let i=-1;i<=1;i++){c.beginPath();c.moveTo(x-r*.48, y+i*r*.34);c.lineTo(x+r*.48,y+i*r*.34);c.stroke()}for(let i=-1;i<=1;i++){c.beginPath();c.moveTo(x+i*r*.32,y-r*.47);c.lineTo(x+i*r*.32,y+r*.47);c.stroke()}}
else if(index===3){for(let i=0;i<3;i++){c.fillStyle=colors[i];c.fillRect(x-r,top+i*2*r/3,2*r,2*r/3)}}
else if(index===0||index===1){for(let i=0;i<3;i++){c.fillStyle=colors[i];c.fillRect(x-r,top+i*2*r/3,2*r,2*r/3)}c.fillStyle='#d82936';c.beginPath();c.moveTo(x-r,top);c.lineTo(x+r*.06,y);c.lineTo(x-r,top+2*r);c.closePath();c.fill();if(index===0){c.fillStyle='#fff';star(c,x-r*.42,y,r*.115,r*.045)}}
else if(index===4){for(let i=0;i<3;i++){c.fillStyle=colors[i];c.fillRect(x-r,top+i*2*r/3,2*r,2*r/3)}c.fillStyle='#d52d39';c.beginPath();c.arc(x,y,r*.18,0,Math.PI*2);c.fill();c.fillRect(x-r*.04,y-r*.22,r*.08,r*.44)}
else if(index===5){c.fillStyle='#168745';c.fillRect(x-r,top,2*r,2*r);c.fillStyle='#f6f7f1';c.fillRect(x-r,top,r*.48,2*r);c.fillStyle='#fff';c.beginPath();c.arc(x+r*.15,y,r*.45,0,Math.PI*2);c.fill();c.fillStyle='#168745';c.beginPath();c.arc(x+r*.31,y-r*.1,r*.38,0,Math.PI*2);c.fill();c.fillStyle='#fff';star(c,x+r*.47,y-r*.29,r*.12,r*.05)}
else if(index===6){c.fillStyle='#e33437';c.fillRect(x-r,top,2*r,2*r);c.fillStyle='#ffdc45';star(c,x-r*.43,top+r*.43,r*.2,r*.08);[[.05,.2],[.3,.4],[.3,.67],[.06,.83]].forEach(([a,b])=>star(c,x-r+a*2*r,top+b*2*r,r*.075,r*.03))}
else{c.fillStyle='#155fa1';c.fillRect(x-r,top,2*r,2*r);c.fillStyle='#fff';c.fillRect(x-r,top+r*.3,2*r,r*.4);c.fillStyle='#d92b3e';c.fillRect(x-r,top+r*.36,2*r,r*.28);c.fillStyle='#fff';star(c,x-r*.48,y,r*.18,r*.07)}
c.restore();c.save();c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.strokeStyle='rgba(16,25,40,.75)';c.lineWidth=Math.max(1.5,r*.09);c.stroke();c.restore();
// Cute countryball eyes
const ex=r*.28,ey=y-r*.02,er=Math.max(1.3,r*.2);for(let s of [-1,1]){c.fillStyle='#fff';c.beginPath();c.ellipse(x+s*ex,ey,er,er*1.18,0,0,Math.PI*2);c.fill();c.fillStyle='#182238';c.beginPath();c.arc(x+s*ex+r*.035,ey+r*.025,er*.52,0,Math.PI*2);c.fill()}}
function star(c,x,y,ro,ri){c.beginPath();for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,r=i%2?ri:ro;c.lineTo(x+Math.cos(a)*r,y+Math.sin(a)*r)}c.closePath();c.fill()}
function makeRoster(){const root=$('roster');racers.forEach((r,i)=>{const b=document.createElement('button');b.className='racer'+(i===selected?' active':'');b.innerHTML=`<canvas width="100" height="100"></canvas><span><b>${r[0]}</b><small>${r[1]} · countryball</small></span>`;drawBall(b.querySelector('canvas').getContext('2d'),50,50,43,i);b.onclick=()=>{selected=i;document.querySelectorAll('.racer').forEach((el,n)=>el.classList.toggle('active',n===i));tone(440+i*30,.06)};root.appendChild(b)})}makeRoster();
function trackX(d){let a=(d%TRACK)/TRACK*Math.PI*2;return Math.sin(a)*380+Math.sin(a*2+1)*120+Math.sin(a*3)*38}
function project(z){let t=Math.max(0,Math.min(1,1-z/VIEW));return H*.345+(H*.64)*t*t}
function roadCenter(z){let p=(player.distance%TRACK+TRACK)%TRACK,delta=trackX(p+z)-trackX(p);return W*.5+delta/500*W*.24*(1-z/VIEW)}
function bg(){let sky=ctx.createLinearGradient(0,0,0,H*.5);sky.addColorStop(0,'#59bdec');sky.addColorStop(.68,'#b3e6ee');sky.addColorStop(1,'#ffd3a0');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let sunX=W*.77,sunY=H*.21;let gl=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,100);gl.addColorStop(0,'#fff5ceaa');gl.addColorStop(1,'#fff5ce00');ctx.fillStyle=gl;ctx.fillRect(sunX-105,sunY-105,210,210);ctx.fillStyle='#fff1c8';ctx.beginPath();ctx.arc(sunX,sunY,28,0,Math.PI*2);ctx.fill();
for(let layer=0;layer<2;layer++){ctx.beginPath();ctx.moveTo(0,H*.36);for(let x=0;x<=W+10;x+=12){let yy=H*(.29+layer*.045)+Math.sin(x*.006+layer*2)*H*.035+Math.sin(x*.014+layer)*H*.012;ctx.lineTo(x,yy)}ctx.lineTo(W,H*.44);ctx.lineTo(0,H*.44);ctx.closePath();ctx.fillStyle=layer?'#9acb9a':'#83b9aa';ctx.fill()}
ctx.fillStyle='#66a850';ctx.fillRect(0,H*.35,W,H*.65)}
function quad(x1,y1,x2,y2,x3,y3,x4,y4,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.lineTo(x3,y3);ctx.lineTo(x4,y4);ctx.closePath();ctx.fill()}
function drawRoad(){const step=48;for(let z=VIEW;z>0;z-=step){let zn=Math.max(0,z-step),yf=project(z),yn=project(zn),cf=roadCenter(z),cn=roadCenter(zn),wf=(W*.49*(1-z/VIEW)**.88)+1.5,wn=(W*.49*(1-zn/VIEW)**.88)+1.5;let stripe=Math.floor((player.distance+z)/165)%2;ctx.fillStyle=stripe?'#69aa52':'#76b957';ctx.fillRect(0,yf,W,yn-yf+1);let curbF=wf*1.09,curbN=wn*1.09;quad(cf-curbF,yf,cf-curbF*.88,yf,cn-curbN*.88,yn,cn-curbN,yn,stripe?'#fff':'#eb4a50');quad(cf+curbF*.88,yf,cf+curbF,yf,cn+curbN,yn,cn+curbN*.88,yn,stripe?'#fff':'#eb4a50');quad(cf-wf,yf,cf+wf,yf,cn+wn,yn,cn-wn,yn,stripe?'#454a56':'#424650');if(stripe){for(let lane of [-1/3,1/3]){let xf=cf+wf*lane,xn=cn+wn*lane;quad(xf-wf*.009,yf,xf+wf*.009,yf,xn+wn*.009,yn,xn-wn*.009,yn,'#ffffffaa')}}}
// Start gantry and roadside flags on the horizon are scenery
}

function drawTree(x,y,s,variant){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#75523b';ctx.fillRect(-5,-28,10,30);ctx.fillStyle=variant?'#287c5b':'#319260';for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(0,-32-i*12,19-i*2,16,0,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawKart(x,y,s,index,playerKart=false,spark=false){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#07101c55';ctx.beginPath();ctx.ellipse(0,6,31,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#151b28';ctx.fillRect(-27,-9,10,19);ctx.fillRect(17,-9,10,19);ctx.fillStyle=playerKart?'#c8ff55':['#e56b61','#63ccf0','#dfa958','#af8bea','#e678a8','#8bd37c','#71a2f6'][index%7];ctx.beginPath();ctx.moveTo(-26,-13);ctx.lineTo(-19,-24);ctx.lineTo(17,-24);ctx.lineTo(27,-13);ctx.lineTo(24,3);ctx.lineTo(-23,3);ctx.closePath();ctx.fill();ctx.strokeStyle='#ffffff99';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#e6f4ff';ctx.fillRect(-16,-19,8,3);ctx.fillRect(9,-19,8,3);ctx.fillStyle='#ff514e';ctx.fillRect(-18,0,9,4);ctx.fillRect(10,0,9,4);drawBall(ctx,0,-37,19,index);if(spark){ctx.fillStyle='#ffd746';for(let i=0;i<5;i++){let a=Math.random()*Math.PI*2,rr=26+Math.random()*13;ctx.beginPath();ctx.arc(Math.cos(a)*rr,Math.sin(a)*rr-8,2+Math.random()*2,0,Math.PI*2);ctx.fill()}}ctx.restore()}
function drawBox(z,lateral){let t=1-z/VIEW,half=W*.49*t**.88+1.5,x=roadCenter(z)+lateral*half*.72,y=project(z),s=.22+t*.74;ctx.save();ctx.translate(x,y-20*s);ctx.scale(s,s);ctx.rotate(Math.sin(performance.now()*.003+z)*.12);ctx.shadowColor='#ffe36a';ctx.shadowBlur=14;ctx.fillStyle='#ffe36a';ctx.fillRect(-13,-13,26,26);ctx.shadowBlur=0;ctx.strokeStyle='#fff9c9';ctx.lineWidth=2;ctx.strokeRect(-13,-13,26,26);ctx.fillStyle='#35415a';ctx.font='bold 19px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('?',0,1);ctx.restore()}
function drawScene(){bg();drawRoad();let entities=[];for(let i=0;i<ais.length;i++){let rel=ais[i].distance-player.distance;if(rel<0)rel+=TRACK*5;if(rel>0&&rel<VIEW)entities.push({type:'kart',z:rel,lateral:ais[i].lane,index:ais[i].country,i})}for(let b of boxLocations){let d=(b-(player.distance%TRACK)+TRACK)%TRACK;if(d>0&&d<VIEW)entities.push({type:'box',z:d,lateral:Math.sin(b)*.45})}entities.sort((a,b)=>b.z-a.z);for(let z=VIEW;z>80;z-=210){let y=project(z),t=1-z/VIEW,half=W*.49*t**.88;let sceneryCycle=(Math.floor((player.distance+z)/210)%2);drawTree(roadCenter(z)-half*1.28,y,Math.max(.15,t*.8),sceneryCycle);drawTree(roadCenter(z)+half*1.28,y,Math.max(.15,t*.8),1-sceneryCycle)}for(let e of entities){if(e.type==='box')drawBox(e.z,e.lateral);else{let t=1-e.z/VIEW,half=W*.49*t**.88+1.5;drawKart(roadCenter(e.z)+e.lateral*half*.68,project(e.z)-9,.22+t*.8,e.index,false,false)}}let near=125,half=W*.49*(1-near/VIEW)**.88;drawKart(roadCenter(near)+player.lateral*half*.72,H*.812,1.08,selected,true,player.drift>.2&&Math.abs(player.steer||0)>.05)}
function tone(freq=500,dur=.1){try{beepCtx??=new(window.AudioContext||window.webkitAudioContext)();let o=beepCtx.createOscillator(),g=beepCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,beepCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,beepCtx.currentTime+dur);o.connect(g);g.connect(beepCtx.destination);o.start();o.stop(beepCtx.currentTime+dur)}catch(e){}}
function showToast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),1350)}function ordinal(n){return n+(n%100>=11&&n%100<=13?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th'))}
function begin(){player={distance:0,lateral:0,speed:0,item:false,boost:0,drift:0,lap:1,elapsed:0,steer:0};ais=racers.map((_,i)=>({country:i,distance:85+i*53,lane:[-.52,.46,-.15,.62,-.63,.18,.4][i],pace:224+(i%4)*8+Math.random()*8,phase:Math.random()*9}));$('menu').classList.add('hidden');$('finish').classList.add('hidden');$('pauseScreen').classList.add('hidden');$('hud').classList.add('visible');$('touch').style.display='';mode='countdown';player.countAt=performance.now();$('countdown').classList.remove('hidden');$('countdown').textContent='3';tone(440,.13);last=performance.now()}
function useItem(){if(mode!=='race')return;if(player.item){player.item=false;player.boost=2.15;tone(880,.2);showToast('Turbo boost!');$('item-text').textContent='Find an item box'}else showToast('No boost yet!')}
function pause(){if(mode==='race'||mode==='countdown'){mode='paused';$('pauseScreen').classList.remove('hidden');$('countdown').classList.add('hidden')}}function resume(){if(mode==='paused'){mode='race';$('pauseScreen').classList.add('hidden');last=performance.now()}}
$('start').onclick=begin;$('pause').onclick=pause;$('resume').onclick=resume;$('quit').onclick=()=>{mode='menu';$('pauseScreen').classList.add('hidden');$('hud').classList.remove('visible');$('menu').classList.remove('hidden')};$('again').onclick=begin;
addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','shift'].includes(k))e.preventDefault();keys[k]=true;if((k==='escape'||k==='p')&&mode==='race')pause();else if((k==='escape'||k==='p')&&mode==='paused')resume();if((k==='x'||k==='shift')&&!e.repeat)useItem()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{keys={};if(mode==='race')pause()});
document.querySelectorAll('.touch-btn').forEach(b=>{const c=b.dataset.control;const down=e=>{e.preventDefault();touch[c]=true;b.classList.add('down');b.setPointerCapture?.(e.pointerId)};const up=e=>{e.preventDefault();touch[c]=false;b.classList.remove('down')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up);if(c==='item')b.addEventListener('click',useItem)});
function controls(){return{left:keys.arrowleft||keys.a||touch.left,right:keys.arrowright||keys.d||touch.right,acc:keys.arrowup||keys.w||touch.accelerate,brake:keys.arrowdown||keys.s||touch.brake,drift:keys[' ']||touch.drift}}
function update(dt,now){if(mode==='countdown'){let n=3-Math.floor((now-player.countAt)/700);if(n<=0){mode='race';$('countdown').classList.add('hidden');tone(660,.25);last=now}else{$('countdown').textContent=n;return}}if(mode!=='race')return;let c=controls();player.elapsed+=dt;player.steer=(c.right?1:0)-(c.left?1:0);let target=c.acc?MAXSPEED:Math.max(0,player.speed-25);if(c.brake)target=80;player.speed+=(target-player.speed)*Math.min(1,dt*(target>player.speed?1.2:2.4));if(player.boost>0){player.boost=Math.max(0,player.boost-dt);player.speed=Math.min(385,player.speed+185*dt)}let drifting=c.drift&&Math.abs(player.steer)>.1&&player.speed>85;if(drifting){player.drift+=dt;player.speed=Math.min(MAXSPEED+8,player.speed+15*dt)}else{if(player.drift>.58){player.boost=Math.max(player.boost,.95);tone(720,.13);showToast('Mini-turbo!')}player.drift=Math.max(0,player.drift-dt*2.5)}let steerRate=1.15*(.35+player.speed/MAXSPEED*.65);player.lateral+=player.steer*steerRate*dt*(drifting?1.24:1);player.lateral*=Math.pow(.985,dt*60);if(Math.abs(player.lateral)>.88){player.speed=Math.max(70,player.speed-120*dt);player.lateral=Math.max(-1.16,Math.min(1.16,player.lateral))}let old=player.distance;player.distance+=player.speed*dt;player.lap=Math.min(LAPS,Math.floor(player.distance/TRACK)+1);if(player.distance>=TRACK*LAPS){finishRace();return}for(let ai of ais){ai.distance+=ai.pace*dt*(.985+Math.sin(player.elapsed*.8+ai.phase)*.025);let rel=ai.distance-player.distance;if(rel>-40&&rel<40&&Math.abs(player.lateral-ai.lane)<.28){player.speed=Math.max(85,player.speed-95*dt);ai.distance+=30*dt}}
for(let b of boxLocations){let prev=(b-(old%TRACK)+TRACK)%TRACK,nowD=(b-(player.distance%TRACK)+TRACK)%TRACK;if((nowD<30&&prev>nowD)||nowD<player.speed*dt+4){if(Math.abs(player.lateral-Math.sin(b)*.45)<.5&&!player.item){player.item=true;$('item-text').textContent='BOOST READY · SHIFT / X';tone(640,.16);showToast('Boost acquired!');break}}}
if(Math.abs(player.lateral)>.96&&player.speed>100)player.speed-=35*dt;updateHud()}
function updateHud(){let rank=1+ais.filter(a=>a.distance>player.distance).length;$('lap').innerHTML=`${player.lap} <span>/ ${LAPS}</span>`;$('position').textContent=ordinal(rank);$('speed').textContent=Math.round(player.speed);$('progress').style.width=Math.min(100,player.distance/(TRACK*LAPS)*100)+'%';if(player.boost>0){$('speed').style.color='#c8ff55'}else $('speed').style.color=''}
function finishRace(){mode='finish';$('hud').classList.remove('visible');$('touch').style.display='none';let rank=1+ais.filter(a=>a.distance>player.distance).length;$('finish-title').textContent=rank===1?'Champion!':rank<=3?'Podium finish!':'Race complete!';$('finish-copy').textContent=`${racers[selected][0]} crossed the line ${ordinal(rank)} out of 8.`;$('medal').textContent=rank===1?'🏆':rank<=3?'🥈':'🏁';$('finish-time').textContent=`Race time · ${(player.elapsed/60|0)}:${String(player.elapsed%60|0).padStart(2,'0')}`;$('finish').classList.remove('hidden');tone(rank===1?950:560,.35)}

