function drawBall(c,x,y,r,index){c.save();c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.clip();const top=y-r;let colors=[['#111','#fff','#168c49'],['#111','#fff','#168c49'],['#fff','#fff','#fff'],['#fff','#2455a5','#e33b44'],['#169447','#fff','#e63d43'],['#138746','#138746','#138746'],['#e33336','#e33336','#e33336'],['#1664a2','#df2635','#1664a2']][index];
