 function drawScene(){bg();drawRoad();let entities=[];for(let i=0;i<ais.length;i++){let rel=ais[i].distance-player.distance;if(rel<0)rel+=TRACK*5;if(rel>0&&rel<VIEW)entities.push({type:'kart',z:rel,lateral:ais[i].lane,index:ais[i].country,i})}for(let b of boxLocations){let d=(b-(player.distance%TRACK)+TRACK)%TRACK;if(d>0&&d<VIEW)entities.push({type:'box',z:d,lateral:Math.sin(b)*.45})}entities.sort((a,b)=>b.z-a.z);for(let z=VIEW;z>80;z-=210){let y=project(z),t=1-z/VIEW,half=W*.49*t**.88;let sceneryCycle=(Math.floor((player.distance+z)/210)%2);drawTree(roadCenter(z)-half*1.28,y,Math.max(.15,t*.8),sceneryCycle);drawTree(roadCenter(z)+half*1.28,y,Math.max(.15,t*.8),1-sceneryCycle)}for(let e of entities){if(e.type==='box')drawBox(e.z,e.lateral);else{let t=1-e.z/VIEW,half=W*.49*t**.88+1.5;drawKart(roadCenter(e.z)+e.lateral*half*.68,project(e.z)-9,.22+t*.8,e.index,false,false)}}let near=125,half=W*.49*(1-near/VIEW)**.88;drawKart(roadCenter(near)+player.lateral*half*.72,H*.812,1.08,selected,true,player.drift>.2&&Math.abs(player.steer||0)>.05)}

input.command:
node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.locator('#start').click();
await page.waitForTimeout(2400);
await page.keyboard.down('ArrowUp');
await page.waitForTimeout(1300);
await page.keyboard.up('ArrowUp');
const state = await page.evaluate(() => ({
  mode: document.querySelector('#hud').classList.contains('visible') ? 'race' : 'menu',
  position: document.querySelector('#position').textContent,
  racers: document.querySelectorAll('#roster .racer').length,
  speed: document.querySelector('#speed').textContent,
}));
await page.screenshot({ path: '/tmp/opencode/countryballs-check/race.png' });
console.log(JSON.stringify({ state, errors }, null, 2));
await browser.close();
EOF
